{"kind":"stack","id":"s1","title":"Appliances that run on electricity","theme":{"background":"#fdf6e3","foreground":"#073642","font":"Arial, sans-serif"}}
{"kind":"card","card":{"id":"c1","kind":"flash","elements":[{"type":"text","id":"c1-t","content":"Electricity"},{"type":"text","id":"c1-d","content":"A form of energy that flows through wires and powers many machines in our homes and schools."},{"type":"button","id":"c1-b","label":"Next Card","actions":[{"type":"goto","cardId":"c2"}]}],"actions":[]}}
